    p.advance(ATTEMPT_DEADLINE);
    p.advance(Duration::from_millis(1100));
    let second = p.a.k.sent.last().unwrap().clone();
    assert_ne!(first, second);
    p.deliver_b(&second);
    assert!(p.b.ctl.is_established(1));
