    let init = p.a.k.sent[0].clone();
    p.deliver_b(&init);
    let resp = p.b.k.sent.last().unwrap().clone();
    p.now += ATTEMPT_DEADLINE - Duration::from_millis(1);
    p.deliver_a(&resp);
    assert_eq!(p.a.k.staged.len(), 1);
    assert!(p.a.ctl.is_established(1));
}

